{"code": "checkpoint = torch.load('checkpoint.pth')
class_to_idx = checkpoint['class_to_idx']

# Create idx_to_class mapping
idx_to_class = {v: k for k, v in class_to_idx.items()}

print("class_to_idx (first 5):", dict(list(class_to_idx.items())[:5]))
print("idx_to_class (first 5):", dict(list(idx_to_class.items())[:5]))

# Check if idx_to_class values are strings or integers
print("\nFirst few idx_to_class values:")
for idx in range(5):
    print(f"  idx {idx} -> {idx_to_class[idx]} (type: {type(idx_to_class[idx])})")"}

